{"results": [{"id": "hp_doc_b00f198c4ba055b9cb1be601c73dc9246dc774fb45fa554a21949c0d03e4a577", "title": "Noble (film)", "text": "Noble is a 2014 film written and directed by Stephen Bradley about the true life story of Christina Noble, a children's rights campaigner, charity worker and writer, who founded the Christina Noble Children's Foundation in 1989. It stars Deirdre O'Kane, Sarah Greene, Brendan Coyle, Mark Huberman and Ruth Negga.", "score": 22.0712}, {"id": "hp_doc_c59416d241acb4bbb477c4eb5465d4ee2a8bfc510df608693dc1e962d53ba53a", "title": "Sally Prouty", "text": "Sally Prouty (born Sarah Green) (December 23, 1922 - September 7, 2014) was an American retired table tennis champion. She was inducted into the United States of America Table Tennis (USATT) Hall of Fame in 1979.", "score": 17.3965}, {"id": "hp_doc_edacf566f6f75b3b3847d3a5c0d41e1c8a31a6f45114685af93538f41e8e0804", "title": "Sarah Green (film producer)", "text": "Sarah Green is a film producer. She currently sits on the National Board of Directors for the Producers Guild of America. On January 24, 2012, she was nominated for an Academy Award for the film \"The Tree of Life.\"", "score": 16.5231}], "remaining_searches": 2}
